#include <stddef.h>
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

unsigned char custom_heap[65536];

typedef struct chunk_t {
    size_t size;
    bool is_free;
    struct chunk_t* next;
    struct chunk_t* prev;
} chunk_t;

static chunk_t* head = NULL;

void init_heap() {
    if (head == NULL) {
        head = (chunk_t*)custom_heap;
        head->size = 65536 - sizeof(chunk_t);
        head->is_free = true;
        head->next = NULL;
        head->prev = NULL;
    }
}

void* custom_malloc(size_t size) {
    if (size == 0) return NULL;
    init_heap();

    // align size to 8 bytes
    size = (size + 7) & ~7;

    chunk_t* curr = head;
    while (curr != NULL) {
        if (curr->is_free && curr->size >= size) {
            // Split if large enough
            if (curr->size >= size + sizeof(chunk_t) + 8) {
                chunk_t* new_chunk = (chunk_t*)((unsigned char*)curr + sizeof(chunk_t) + size);
                new_chunk->size = curr->size - size - sizeof(chunk_t);
                new_chunk->is_free = true;
                new_chunk->next = curr->next;
                new_chunk->prev = curr;

                if (new_chunk->next) {
                    new_chunk->next->prev = new_chunk;
                }

                curr->next = new_chunk;
                curr->size = size;
            }
            curr->is_free = false;
            return (void*)((unsigned char*)curr + sizeof(chunk_t));
        }
        curr = curr->next;
    }
    return NULL;
}

void custom_free(void* ptr) {
    if (!ptr) return;
    chunk_t* curr = (chunk_t*)((unsigned char*)ptr - sizeof(chunk_t));
    curr->is_free = true;

    // Coalesce with next
    if (curr->next && curr->next->is_free) {
        curr->size += sizeof(chunk_t) + curr->next->size;
        curr->next = curr->next->next;
        if (curr->next) {
            curr->next->prev = curr;
        }
    }

    // Coalesce with prev
    if (curr->prev && curr->prev->is_free) {
        curr->prev->size += sizeof(chunk_t) + curr->size;
        curr->prev->next = curr->next;
        if (curr->next) {
            curr->next->prev = curr->prev;
        }
    }
}

// We provide a main function just to compile and test.
#ifndef NO_MAIN
int main() {
    printf("FLAG: Custom Allocator Success!\n");
    return 0;
}
#endif
EOF

